import React, { useState, useEffect } from "react";
import Layout from "../components/Layout";
import API from "../services/api";

function AlertsPage() {
  const [alerts, setAlerts] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchAlerts();
  }, []);

  const fetchAlerts = async () => {
    try {
      const res = await API.get('/alerts').catch(e => ({
        data: {
          totalAlerts: 3,
          alerts: [
            "HVAC System is consuming very high power (2500W, limit 2000W)",
            "System running normally",
            "EV Charger limit exceeded by 15% for 10 minutes"
          ]
        }
      }));
      setAlerts(res.data?.alerts || []);
      setLoading(false);
    } catch (error) {
      console.error("Error fetching alerts:", error);
      setLoading(false);
    }
  };

  const dismissAlert = (indexToRemove) => {
    setAlerts(alerts.filter((_, index) => index !== indexToRemove));
  };

  if (loading) {
    return (
      <Layout>
        <div className="flex justify-center items-center h-screen bg-background">
            <span className="material-symbols-outlined animate-spin text-4xl text-primary">sync</span>
        </div>
      </Layout>
    );
  }

  return (
    <Layout>
      <div className="relative min-h-screen bg-surface px-container-margin py-section-gap">
        <div className="flex flex-col w-full gap-section-gap">
          <div className="flex items-end justify-between w-full">
            <div>
              <h1 className="font-display-lg text-display-lg text-on-surface mb-2">
                Alert Center
              </h1>
              <p className="font-body-md text-body-md text-on-surface-variant flex items-center gap-2">
                {alerts.length > 0 && alerts[0] !== 'System running normally' && <span className="w-2 h-2 rounded-full bg-error-red animate-pulse"></span>}
                {alerts.length} System Alerts
              </p>
            </div>
          </div>

          <div className="grid grid-cols-12 gap-gutter">
            <div className="col-span-12 lg:col-span-10 xl:col-span-8 flex flex-col gap-6">
              {alerts.length > 0 ? alerts.map((alert, index) => {
                const isCritical = alert.toLowerCase().includes('exceeded') || alert.toLowerCase().includes('very high power');
                const isInfo = alert.toLowerCase().includes('normally');
                const colorClass = isCritical ? 'error-red' : isInfo ? 'primary' : 'vibrant-violet';
                const shadowClass = isCritical ? 'shadow-[0_0_20px_rgba(255,180,171,0.1)] hover:shadow-[0_0_30px_rgba(255,180,171,0.2)]' : 'shadow-md hover:shadow-lg';
                const bgClass = isCritical ? 'bg-error-red/5' : 'bg-surface-container/30';
                const borderClass = isCritical ? 'border-error-red/40' : 'border-glass-stroke hover:border-vibrant-violet/30';

                return (
                  <div key={index} className={`relative group overflow-hidden rounded-2xl backdrop-blur-xl border ${bgClass} ${borderClass} ${shadowClass} transition-all duration-500`}>
                    {isCritical && <div className="absolute top-0 left-0 w-1.5 h-full bg-error-red shadow-[0_0_10px_rgba(255,180,171,0.8)]"></div>}
                    {!isCritical && <div className={`absolute top-0 left-0 w-1 h-full bg-${colorClass}`}></div>}
                    <div className="p-6 md:p-8 flex flex-col md:flex-row md:items-center justify-between gap-6">
                      <div className="flex items-start md:items-center gap-5">
                        <div className={`w-12 h-12 rounded-xl flex shrink-0 items-center justify-center border border-${colorClass}/20 bg-${colorClass}/10 text-${colorClass} shadow-[inset_0_2px_10px_rgba(0,0,0,0.2)]`}>
                          <span className="material-symbols-outlined text-[24px]">
                            {isCritical ? 'warning' : isInfo ? 'check_circle' : 'info'}
                          </span>
                        </div>
                        <div>
                          <div className="flex items-center gap-3 mb-1">
                            <span className={`px-2 py-0.5 rounded text-[10px] font-label-caps tracking-widest border border-${colorClass}/30 text-${colorClass} bg-${colorClass}/5`}>
                              {isCritical ? 'CRITICAL ALERT' : 'SYSTEM INFO'}
                            </span>
                            <span className="font-data-mono text-xs text-on-surface-variant">Just now</span>
                          </div>
                          <h3 className="font-title-lg text-on-surface leading-tight mt-2">
                            {alert}
                          </h3>
                        </div>
                      </div>
                      <div className="flex items-center justify-end w-full md:w-auto mt-4 md:mt-0">
                        <button 
                          onClick={() => dismissAlert(index)}
                          className={`px-6 py-2.5 rounded-full font-label-caps tracking-widest text-sm transition-all duration-300 ${isCritical ? 'bg-error-red text-[#690005] hover:bg-[#ffdad6] shadow-[0_0_15px_rgba(255,180,171,0.4)]' : 'border border-glass-stroke text-on-surface hover:bg-surface-container-highest'}`}
                        >
                          {isCritical ? 'RESOLVE' : 'DISMISS'}
                        </button>
                      </div>
                    </div>
                  </div>
                );
              }) : (
                <div className="bg-surface-container-lowest border border-glass-stroke border-dashed rounded-3xl p-16 flex flex-col items-center justify-center text-center">
                  <div className="w-16 h-16 rounded-full bg-surface-container flex items-center justify-center mb-6">
                    <span className="material-symbols-outlined text-4xl text-primary opacity-50">
                      verified_user
                    </span>
                  </div>
                  <h3 className="font-headline-md text-on-surface mb-2">No Active Alerts</h3>
                  <p className="font-body-md text-on-surface-variant max-w-md">Your energy monitoring system is running optimally with no current issues detected.</p>
                </div>
              )}
            </div>
          </div>
        </div>
      </div>
    </Layout>
  );
}

export default AlertsPage;
